import { createAudioPlayer, setAudioModeAsync, type AudioPlayer } from 'expo-audio';
import * as Haptics from 'expo-haptics';
import { useProgress } from '@/data/progressStore';

/** All effects are bundled with the app (generated by scripts/generate-sfx.mjs) – never fetched. */
const SOURCES = {
  tap: require('../../assets/sfx/tap.wav'),
  pop: require('../../assets/sfx/pop.wav'),
  correct: require('../../assets/sfx/correct.wav'),
  tryAgain: require('../../assets/sfx/tryAgain.wav'),
  flip: require('../../assets/sfx/flip.wav'),
  levelUp: require('../../assets/sfx/levelUp.wav'),
  sticker: require('../../assets/sfx/sticker.wav'),
} as const;

export type Sfx = keyof typeof SOURCES;

const players: Partial<Record<Sfx, AudioPlayer>> = {};
let ready = false;

/** Create one player per effect up front so the first tap has no latency. */
export async function initAudio() {
  if (ready) return;
  ready = true;
  try {
    await setAudioModeAsync({ playsInSilentMode: true, shouldPlayInBackground: false });
  } catch {}
  (Object.keys(SOURCES) as Sfx[]).forEach((k) => {
    players[k] = createAudioPlayer(SOURCES[k]);
  });
}

const settings = () => {
  const s = useProgress.getState();
  return s.activeId ? s.profiles[s.activeId]?.settings : undefined;
};

const HAPTIC: Partial<Record<Sfx, () => Promise<void>>> = {
  correct: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  tryAgain: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),
  levelUp: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),
  tap: () => Haptics.selectionAsync(),
};

export function play(name: Sfx) {
  const s = settings();
  if (s?.haptics !== false) HAPTIC[name]?.().catch(() => {});
  if (s?.sound === false) return;
  const p = players[name];
  if (!p) return;
  p.seekTo(0).catch(() => {});
  p.play();
}
